from pathlib import Path
p=Path('dist/game.js');s=p.read_text(encoding='utf-8')
s=s.replace('round,hp,kills,remaining', 'round,hp,kills,roundKills,roundResults,remaining')
s=s.replace('hp=10;kills=0;', 'hp=10;kills=0;roundKills=0;roundResults=[];')
s=s.replace("function ui(){const cap=", "function ui(){$('round-results').hidden=roundResults.length===0;$('round-results').innerHTML='<b>라운드 방어 기록</b>'+roundResults.map(r=>`<div><span>${r.round}라운드 클리어</span><strong>${r.kills}마리 처치</strong></div>`).join('');const cap=")
s=s.replace("phase='active';remaining=60;", "phase='active';roundKills=0;remaining=60;")
s=s.replace('5개 라운드 클리어 · 적 ${kills}마리 처치', '5개 라운드 클리어 · 이번 라운드 ${roundKills}마리 · 총 ${kills}마리 처치')
s=s.replace('${round}라운드 · 적 ${kills}마리 처치', '${round}라운드 · 이번 라운드 ${roundKills}마리 · 총 ${kills}마리 처치')
s=s.replace('function moveBullet(b,dt){let left=dt;', "function moveBullet(b,dt){let expired=false;if(b.type==='bank'){const life=Math.max(0,4-(b.age??0));if(life<=1e-9)return false;dt=Math.min(dt,life);b.age=(b.age??0)+dt;expired=b.age>=4-1e-9;}let left=dt;")
s=s.replace('kills++;burst', 'kills++;roundKills++;burst')
s=s.replace('return b.x>=0&&b.x<=10&&b.y>=0&&b.y<=10}', 'return !expired&&b.x>=0&&b.x<=10&&b.y>=0&&b.y<=10}')
s=s.replace('type:t.type,contacts:new Set()', 'type:t.type,age:0,contacts:new Set()')
s=s.replace('if(remaining<=0){enemies=[];', 'if(remaining<=0){roundResults.push({round,kills:roundKills});enemies=[];')
s=s.replace('라운드 클리어! 포탑 2개를', '${round-1}라운드 클리어 · ${roundKills}마리 처치! 포탑 2개를')
p.write_text(s,encoding='utf-8')
p=Path('dist/index.html');s=p.read_text(encoding='utf-8').replace('<div class="brief">','<div id="round-results" class="round-results" role="status" hidden></div><div class="brief">')
s=s.replace('1 피해 · 3초 간격 · 관통', '1 피해 · 3초 간격 · 관통 · 수명 4초').replace('적을 관통합니다.', '적을 관통하며 발사 후 4초가 지나면 사라집니다.')
p.write_text(s,encoding='utf-8')
p=Path('dist/style.css');s=p.read_text(encoding='utf-8')+'\n.round-results{padding:14px;margin-bottom:18px;border:1px solid #31545a;background:#142b32;border-radius:6px;font-size:14px}.round-results>b{display:block;color:var(--cyan);margin-bottom:10px}.round-results>div{display:flex;justify-content:space-between;gap:12px;padding:5px 0}.round-results strong{font-weight:500}\n';p.write_text(s,encoding='utf-8')
html=Path('dist/index.html').read_text(encoding='utf-8').replace('<link rel="stylesheet" href="style.css">','<style>'+s+'</style>').replace('<script src="game.js"></script>','<script>'+Path('dist/game.js').read_text(encoding='utf-8')+'</script>')
Path('outputs/nexus-defense.html').write_text(html,encoding='utf-8')
